4: /**
5:  * Bounded, strict view of a waveform payload that arrived from the network.
6:  *
7:  * The declared bar count is read from the payload shape first and rejected
8:  * against the service limit *before* any magnitude is materialised, so an
9:  * oversized payload fails closed instead of being expanded into memory. Only
10:  * genuine unsigned magnitudes survive the read: strings, booleans and nulls are
11:  * malformed rather than silently coerced.
12:  */
13: export class TransportWaveform {
14:   declaredBarCount: number = 0;
15:   bytes: number[] = [];
16:   oversized: boolean = false;
17:   malformed: boolean = false;
18: }
19: 
20: function strictMagnitude(item: Object | undefined): number {
21:   if (typeof item === 'number') {
22:     const value: number = item;
23:     if (Math.round(value) !== value || value < 0 || value > MAX_BAR_MAGNITUDE) {
24:       return -1;
25:     }
26:     return value;
27:   }
28:   return -1;
29: }
30: 
31: /** Bar count declared by a payload field, or -1 when the field is not a valid count. */
32: function declaredCount(source: JsonMap, key: string): number {
33:   const item: Object = source[key];
34:   if (typeof item === 'number') {
35:     const value: number = item;
36:     return Math.round(value) === value && value >= 0 ? value : -1;
37:   }
38:   return -1;
39: }
40: 
41: function overLimit(result: TransportWaveform, limit: number): boolean {
42:   if (result.declaredBarCount > limit) {
43:     result.oversized = true;
44:     return true;
45:   }
46:   return false;
47: }
48: 
49: function isEmptyWaveform(result: TransportWaveform): boolean {
50:   if (result.declaredBarCount === 0) {
51:     result.malformed = true;
52:     return true;
53:   }
54:   return false;
55: }
56: 
57: export function readTransportWaveform(value: Object | undefined, limit: number): TransportWaveform {
58:   const result: TransportWaveform = new TransportWaveform();
59:   if (!isPresent(value)) {
60:     result.malformed = true;
61:     return result;
62:   }
63:   if (Array.isArray(value)) {
64:     const items: Object[] = value as Object[];
65:     result.declaredBarCount = items.length;
66:     if (overLimit(result, limit) || isEmptyWaveform(result)) {
67:       return result;
68:     }
69:     for (let index = 0; index < items.length; index++) {
70:       const magnitude: number = strictMagnitude(items[index]);
71:       if (magnitude < 0) {
72:         result.malformed = true;
73:         return result;
74:       }
75:       result.bytes.push(magnitude);
76:     }
77:     return result;
78:   }
79:   const source: JsonMap = asMap(value);
80:   const segments: JsonMap[] = asMaps(source['segments']);
81:   if (segments.length > 0) {
82:     for (let index = 0; index < segments.length; index++) {
83:       const count: number = declaredCount(segments[index], 'count');
84:       if (count < 0) {
85:         result.malformed = true;
86:         return result;
87:       }
88:       result.declaredBarCount += count;
89:       if (overLimit(result, limit)) {
90:         return result;
91:       }
92:     }
93:     if (isEmptyWaveform(result)) {
94:       return result;
95:     }
96:     for (let index = 0; index < segments.length; index++) {
97:       const segment: JsonMap = segments[index];
98:       const magnitude: number = strictMagnitude(segment['value']);
99:       const count: number = declaredCount(segment, 'count');
100:       if (magnitude < 0) {
101:         result.malformed = true;
102:         return result;
103:       }
104:       for (let bar = 0; bar < count; bar++) {
105:         result.bytes.push(magnitude);
106:       }
107:     }
108:     return result;
109:   }
110:   const barCount: number = declaredCount(source, 'barCount');
111:   if (barCount < 0) {
112:     result.malformed = true;
113:     return result;
114:   }
115:   result.declaredBarCount = barCount;
116:   if (overLimit(result, limit) || isEmptyWaveform(result)) {
117:     return result;
118:   }
119:   const fill: number = strictMagnitude(source['fill']);
120:   if (fill < 0) {
121:     result.malformed = true;
122:     return result;
123:   }
124:   for (let bar = 0; bar < barCount; bar++) {
125:     result.bytes.push(fill);
126:   }
127:   return result;
128: }

