26: /**
27:  * Envelope validation for incoming attachment pointers. Waveform metadata is
28:  * checked before the attachment is persisted or handed to the renderer, so a
29:  * malformed or oversized sender payload can never contaminate attachment state.
30:  */
31: export class IncomingWaveformValidator {
32:   static validate(pointer: JsonMap, limit: number): IncomingWaveformOutcome {
33:     const outcome: IncomingWaveformOutcome = new IncomingWaveformOutcome(limit);
34:     if (isEmptyMap(pointer)) {
35:       outcome.reason = 'missing_attachment_pointer';
36:       return outcome;
37:     }
38:     if (mapText(pointer, 'cdnKey').length === 0) {
39:       outcome.reason = 'missing_cdn_key';
40:       return outcome;
41:     }
42:     const waveform: Object | undefined = pointer['audioWaveform'];
43:     if (waveform === undefined || waveform === null) {
44:       outcome.accepted = true;
45:       return outcome;
46:     }
47:     const transport: TransportWaveform = readTransportWaveform(waveform, outcome.limit);
48:     outcome.barCount = transport.declaredBarCount;
49:     outcome.durationSeconds = mapNumber(pointer, 'audioDurationSeconds');
50:     if (transport.oversized) {
51:       outcome.reason = 'audio_waveform_too_large';
52:       return outcome;
53:     }
54:     if (transport.malformed) {
55:       outcome.reason = 'malformed_audio_waveform';
56:       return outcome;
57:     }
58:     if (!(outcome.durationSeconds > 0)) {
59:       outcome.reason = 'missing_audio_duration';
60:       return outcome;
61:     }
62:     outcome.bytes = transport.bytes;
63:     outcome.accepted = true;
64:     return outcome;
65:   }
66: }

