4: /**
5:  * Decodes the magnitudes of a waveform row this app wrote itself. Stored rows
6:  * reach us in three interchangeable shapes: an explicit magnitude list, a run
7:  * length encoded list of `{ value, count }` segments, or a uniform
8:  * `{ barCount, fill }` description. Remote payloads never come through here:
9:  * they are read bounded and strictly by `readTransportWaveform`.
10:  */
11: export function decodeWaveformMagnitudes(source: JsonMap): number[] {
12:   const explicit: number[] = asNumbers(source['bytes']);
13:   if (explicit.length > 0) {
14:     return explicit;
15:   }
16:   const segments: JsonMap[] = asMaps(source['segments']);
17:   if (segments.length > 0) {
18:     const expanded: number[] = [];
19:     for (let index = 0; index < segments.length; index++) {
20:       const segment: JsonMap = segments[index];
21:       const count: number = mapNumber(segment, 'count');
22:       const value: number = mapNumber(segment, 'value');
23:       for (let bar = 0; bar < count; bar++) {
24:         expanded.push(value);
25:       }
26:     }
27:     return expanded;
28:   }
29:   const barCount: number = mapNumber(source, 'barCount');
30:   if (barCount > 0) {
31:     const fill: number = mapNumber(source, 'fill');
32:     const uniform: number[] = [];
33:     for (let bar = 0; bar < barCount; bar++) {
34:       uniform.push(fill);
35:     }
36:     return uniform;
37:   }
38:   return [];
39: }
40: 
41: function resolveDurationSeconds(source: JsonMap): number {
42:   if (source['durationSeconds'] !== undefined) {
43:     return mapNumber(source, 'durationSeconds');
44:   }
45:   if (source['durationUs'] !== undefined) {
46:     return mapNumber(source, 'durationUs') / 1000000;
47:   }
48:   return 0;
49: }
50: 
51: /**
52:  * The waveform row that belongs to one attachment. Sender provided magnitudes
53:  * are stored verbatim and are never rewritten by generation or rendering.
54:  */
55: export class WaveformRecord {
56:   attachmentId: string = '';
57:   bytes: number[] = [];
58:   durationSeconds: number = 0;
59:   durationUs: number = 0;
60:   senderProvided: boolean = false;
61: 
62:   constructor(attachmentId: string, bytes: number[], durationSeconds: number, senderProvided: boolean) {
63:     this.attachmentId = attachmentId;
64:     this.bytes = bytes;
65:     this.durationSeconds = durationSeconds;
66:     this.durationUs = Math.round(durationSeconds * 1000000);
67:     this.senderProvided = senderProvided;
68:   }
69: 
70:   barCount(): number {
71:     return this.bytes.length;
72:   }
73: 
74:   /** A waveform that came from a sender is retained as-is, whatever its bar count is. */
75:   isSenderProvided(): boolean {
76:     return this.senderProvided;
77:   }
78: 
79:   /** An empty row is the failure marker of an interrupted generation, not silence. */
80:   isPlaceholder(): boolean {
81:     return !this.senderProvided && this.bytes.length === 0;
82:   }
83: 
84:   /** Locally generated rows whose bar count predates the current release are stale. */
85:   isObsoleteGenerated(): boolean {
86:     return !this.senderProvided && this.bytes.length > 0 && !isCurrentGeneratedBarCount(this.bytes.length);
87:   }
88: 
89:   isRenderable(): boolean {
90:     return this.bytes.length > 0;
91:   }
92: 
93:   /** True when this row can be shipped or rendered without touching the decoder. */
94:   isUsable(): boolean {
95:     return this.isRenderable() && (this.senderProvided || isCurrentGeneratedBarCount(this.bytes.length));
96:   }
97: 
98:   origin(): string {
99:     return this.senderProvided ? 'sender' : 'generated';
100:   }
101: 
102:   belongsTo(attachmentId: string): boolean {
103:     return this.attachmentId.length === 0 || this.attachmentId === attachmentId;
104:   }
105: 
106:   toPersistence(): JsonMap {
107:     return jsonMap(['attachmentId', 'bytes', 'barCount', 'durationSeconds', 'durationUs', 'senderProvided', 'origin'],
108:       [this.attachmentId, cloneNumbers(this.bytes), this.bytes.length,
109:         this.durationSeconds, this.durationUs, this.senderProvided, this.origin()]);
110:   }
111: 
112:   /**
113:    * Builds a row from any of the stored waveform shapes. A bare magnitude list
114:    * carries neither duration nor origin, so those fall back to the enclosing
115:    * attachment row instead of being reset.
116:    */
117:   static fromStored(attachmentId: string, stored: Object | undefined, context: JsonMap = jsonMap()): WaveformRecord {
118:     const source: JsonMap = Array.isArray(stored) ? jsonMap() : asMap(stored);
119:     let durationSeconds: number = resolveDurationSeconds(source);
120:     if (durationSeconds <= 0) {
121:       durationSeconds = resolveDurationSeconds(context);
122:     }
123:     const senderProvided: boolean = source['senderProvided'] !== undefined ?
124:       mapBoolean(source, 'senderProvided') : mapBoolean(context, 'senderProvided');
125:     const bytes: number[] = Array.isArray(stored) ? asNumbers(stored) : decodeWaveformMagnitudes(source);
126:     return new WaveformRecord(attachmentId, bytes, durationSeconds, senderProvided);
127:   }
128: 
129:   /** Builds a sender provided row from already validated remote magnitudes. */
130:   static fromSender(attachmentId: string, bytes: number[], durationSeconds: number): WaveformRecord {
131:     return new WaveformRecord(attachmentId, bytes, durationSeconds, true);
132:   }
133: 
134:   static empty(attachmentId: string): WaveformRecord {
135:     return new WaveformRecord(attachmentId, [], 0, false);
136:   }
137: }

